SELECT "REGION", COUNT(*) AS "PARTIAL_count_0", COUNT("ID") AS "PARTIAL_count_1", SUM("SCORE") AS "PARTIAL_sum_2", MIN("TS") AS "PARTIAL_min_3", MAX("TS") AS "PARTIAL_max_4", SUM("SCORE") AS "PARTIAL_avg_sum_5", COUNT("SCORE") AS "PARTIAL_avg_cnt_5", COUNT("SCORE") AS "PARTIAL_stat_cnt_6", CASE WHEN MIN("SCORE") = MAX("SCORE") THEN CAST(MIN("SCORE") AS DOUBLE) ELSE AVG(CAST("SCORE" AS DOUBLE)) END AS "PARTIAL_stat_mean_6", CASE WHEN MIN("SCORE") = MAX("SCORE") THEN 0.0 ELSE VAR_POP(CAST("SCORE" AS DOUBLE)) * COUNT("SCORE") END AS "PARTIAL_stat_m2_6", COUNT("SCORE") AS "PARTIAL_stat_cnt_7", CASE WHEN MIN("SCORE") = MAX("SCORE") THEN CAST(MIN("SCORE") AS DOUBLE) ELSE AVG(CAST("SCORE" AS DOUBLE)) END AS "PARTIAL_stat_mean_7", CASE WHEN MIN("SCORE") = MAX("SCORE") THEN 0.0 ELSE VAR_POP(CAST("SCORE" AS DOUBLE)) * COUNT("SCORE") END AS "PARTIAL_stat_m2_7", COUNT("SCORE") AS "PARTIAL_stat_cnt_8", CASE WHEN MIN("SCORE") = MAX("SCORE") THEN CAST(MIN("SCORE") AS DOUBLE) ELSE AVG(CAST("SCORE" AS DOUBLE)) END AS "PARTIAL_stat_mean_8", CASE WHEN MIN("SCORE") = MAX("SCORE") THEN 0.0 ELSE VAR_POP(CAST("SCORE" AS DOUBLE)) * COUNT("SCORE") END AS "PARTIAL_stat_m2_8", COUNT("SCORE") AS "PARTIAL_stat_cnt_9", CASE WHEN MIN("SCORE") = MAX("SCORE") THEN CAST(MIN("SCORE") AS DOUBLE) ELSE AVG(CAST("SCORE" AS DOUBLE)) END AS "PARTIAL_stat_mean_9", CASE WHEN MIN("SCORE") = MAX("SCORE") THEN 0.0 ELSE VAR_POP(CAST("SCORE" AS DOUBLE)) * COUNT("SCORE") END AS "PARTIAL_stat_m2_9" FROM (aliased) GROUP BY "REGION"